/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountCoffeeCupSize, type CoffeeCupSizeOptions } from "../../components/coffee-cup-size/CoffeeCupSizeEngine.js";
import type { MotionController } from "../../components/coffee-cup-size/motion-runtime";

export function CoffeeCupSize({ options, className }: { options?: CoffeeCupSizeOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountCoffeeCupSize(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="coffee-cup-size" />;
}

